// Fun Gradient Pallet Generator
vec3 pal(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);

    return a + b*cos(6.28318*(c*t+d));
}

// Rotation matrix function
mat2 rotate(float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return mat2(c, -s, s, c);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //NORMALIZE UV from -1 to 1 
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;


    // Get time as T.
    float t = iTime * 5.1;
    float sinT = sin(t);

    // Final Color
    vec3 finCol = vec3(0.,0.,0.);

    // -------------------------//
    //         MOD VALS         //
    // -------------------------//
    float maxLines = .1;
    float size = .99;
    float flashIntensity = .2;

    // -------------------------//
    //      NORMALIZE MODS      //
    // -------------------------//
    maxLines *= 5.;
    flashIntensity *= 20.;

    // -------------------------//
    //         DO CODE          //
    // -------------------------//

    // Apply rotation to UV coordinates
    //uv = rotate(t) * uv;


    //Create particle
    float d = length(uv*size);
    // Determine blacks
    d = smoothstep(d, .3 * sin(t)*sin(flashIntensity * t), .35);


    finCol = pal(sin(maxLines*(sin(t)+2.) * uv.y * d))*d;

    //fragColor = vec4(d,d,d, 1.0);

    fragColor = vec4(finCol, 1.0);
}
